import {label,creditsOf} from './planner.js';
import {courseFinder,bindCourseFinder} from './course-finder.js';
import {currentCourse,languagePlacementHint} from './course-details.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,text,extra='')=>`<button type="button" class="button secondary" data-action="${action}" ${extra}>${text}</button>`;
export function boardTerms(plan,filter='all'){
 return plan.terms.filter(t=>filter==='unplaced'?t.id==='pending':filter==='remaining'?t.id!=='prior'&&(!t.courses.length||t.courses.some(id=>plan.tracking?.[id]?.status!=='completed')):true);
}
export function semesterBoard(plan,runtime={}){
 const busy=!!(runtime.busy||runtime.dashboardBusy),terms=boardTerms(plan,runtime.semesterFilter),open=runtime.boardOpen||{},map=new Map(plan.courses.map(c=>[c.id,c]));
 const firstRemaining=plan.terms.find(t=>!['prior','pending'].includes(t.id)&&t.courses.some(id=>plan.tracking?.[id]?.status!=='completed'))?.id;
 const defaultOpen=t=>t.id===(runtime.selectedTerm||firstRemaining)||t.id==='pending'&&t.courses.length||t.courses.some(id=>plan.tracking?.[id]?.status==='in-progress');
 const sections=terms.map(t=>{
  const list=t.courses.map(id=>map.get(id)).filter(Boolean),done=list.filter(c=>t.id==='prior'||plan.tracking?.[c.id]?.status==='completed').length;
  const rows=list.map(raw=>{const c=currentCourse(raw,plan.profile),status=plan.tracking?.[c.id]?.status||(t.id==='prior'?'completed':'planned'),hint=languagePlacementHint(c);
   return `<div class="semester-row ${runtime.boardLastCourse===c.id?'semester-row-updated':''}" data-board-row="${esc(c.id)}"><div class="board-course"><button type="button" class="course-drag" draggable="false" data-drag-course="${esc(c.id)}" data-action="dashboard-course" data-course-id="${esc(c.id)}" aria-label="Drag or edit ${esc(c.title)}" title="Drag to another semester, or click to edit" ${busy?'disabled':''}>⠿</button><div><button type="button" class="board-course-name" data-board-course="${esc(c.id)}" aria-label="Edit ${esc(c.title)}" data-action="dashboard-course" data-course-id="${esc(c.id)}" ${busy?'disabled':''}>${esc(c.title)}</button>${hint?`<span class="course-placement-note">${esc(hint)}</span>`:''}</div></div><span class="board-code" data-label="Code">${esc(c.code||'Placement / choice')}</span><span class="board-credits" data-label="Credits">${c.credits}</span><select class="board-status" data-board-status="${esc(c.id)}" aria-label="Progress for ${esc(c.title)}" ${busy?'disabled':''}>${[['planned','Planned'],['in-progress','Taking now'],['completed','Passed'],['retake','Retake']].map(([id,name])=>`<option value="${id}" ${id===status?'selected':''}>${name}</option>`).join('')}</select><div class="board-row-actions"><select class="board-move" data-board-move="${esc(c.id)}" aria-label="Move ${esc(c.title)} to a semester" ${busy?'disabled':''}><option value="">Move to…</option>${plan.terms.filter(x=>x.id!==t.id&&x.id!=='prior').map(x=>`<option value="${esc(x.id)}">${esc(label(x))}</option>`).join('')}</select><button type="button" class="board-remove" data-action="dashboard-remove-course" data-course-id="${esc(c.id)}" aria-label="Remove ${esc(c.title)}" title="Remove course (undo available)" ${busy?'disabled':''}>×</button></div></div>`;
  }).join('');
  return `<details class="semester-section ${t.id==='pending'?'semester-section-pending':''}" data-board-term="${esc(t.id)}" ${Object.hasOwn(open,t.id)?open[t.id]?'open':'':defaultOpen(t)?'open':''}><summary><span class="semester-chevron" aria-hidden="true">›</span><span><strong>${esc(label(t))}</strong>${t.lc?'<small>Language Center</small>':''}</span><span class="semester-summary-count">${list.length} ${list.length===1?'course':'courses'} · ${creditsOf(list)} credits</span><span class="semester-summary-progress">${done}/${list.length} passed</span></summary><div class="semester-body" data-drop-term="${esc(t.id)}"><div class="semester-section-tools">${button('dashboard-add-course','+ Add course',`data-term="${esc(t.id)}" ${busy?'disabled':''}`)}${button('dashboard-term-note',t.note?'Edit note':'Add note',`data-term="${esc(t.id)}" ${busy?'disabled':''}`)}${!list.length&&!['prior','pending'].includes(t.id)?button('dashboard-remove-term','Remove semester',`data-term="${esc(t.id)}" ${busy?'disabled':''}`):''}</div>${t.note?`<div class="semester-note"><span class="dashboard-kicker">KEEP IN MIND</span><p>${esc(t.note)}</p></div>`:''}<div class="semester-column-head" aria-hidden="true"><span>Course</span><span>Code</span><span>Credits</span><span>Progress</span><span>Move / remove</span></div>${rows||`<div class="semester-empty">${t.id==='pending'?'No courses are waiting for placement.':'This semester is empty.'}${t.lc?' Reserved for Language Center.':''} <span>Drop a course here or use Add course.</span></div>`}<div class="semester-drop-hint" aria-hidden="true">Drop here to move to ${esc(label(t))}</div></div></details>`;
 }).join('');
 return `<section class="semester-board" aria-label="Whole degree plan"><div class="semester-board-toolbar"><div class="board-expand-actions">${button('dashboard-expand-terms','Expand all')}${button('dashboard-collapse-terms','Collapse all')}${button('dashboard-current-terms','Current / unplaced')}</div><label>Show <select data-board-filter aria-label="Filter semesters"><option value="all" ${!runtime.semesterFilter||runtime.semesterFilter==='all'?'selected':''}>All semesters</option><option value="remaining" ${runtime.semesterFilter==='remaining'?'selected':''}>Remaining study</option><option value="unplaced" ${runtime.semesterFilter==='unplaced'?'selected':''}>Needs placement</option></select></label>${courseFinder(busy)}</div><p class="manual-edit-hint">Drag ⠿ between semesters, or use Move to. Change progress here; click a course for details. Your changes save here. Manual edits use no AI allowance.</p><details class="board-help"><summary>Quick editing guide</summary><ul><li>Find a course by name or code to jump straight to its semester.</li><li>Open any semester to see its courses. Expand all gives you the whole plan.</li><li>Drag a course's ⠿ handle onto another semester, including a collapsed one. On touch or keyboard, use Move to.</li><li>Use the progress menu to mark Passed, Taking now or Retake. Click a course name for its full editor.</li><li>Add courses within a semester. Remove a course with ×; an empty semester can also be removed. Undo restores your last manual change.</li><li>Your edits save to this workspace. A degree-change preview still needs Save this plan. Excel includes notes, credit totals and Needs placement.</li></ul></details>${runtime.boardError?`<p class="dashboard-error" role="alert">${esc(runtime.boardError)}</p>`:''}<p class="board-live" role="status" aria-live="polite">${esc(runtime.boardNotice||'')}</p><div class="semester-stack">${sections||(plan.terms.length?'<p class="manual-empty">No semesters match this view. Choose All semesters to see your whole plan.</p>':'<p class="manual-empty">Add a semester to begin.</p>')}</div></section>`;
}

// Native drag/drop plus the visible Move to select share the same validated edit.
// Keep drag state in this browser only; no course or academic data leaves the app.
export function bindSemesterBoard(root,controller){
 bindCourseFinder(root,controller);
 let dragged='';const section=e=>e.target.closest?.('[data-board-term]');
 const clear=()=>root.querySelectorAll('.semester-drop-active').forEach(x=>x.classList.remove('semester-drop-active'));
 // Pointer-driven handles work with mouse, pen and touch. Prevent the browser's
 // native drag image from stealing pointer capture; keep native handlers below
 // as a progressive fallback for supported drag event sources.
 const doc=root.ownerDocument||root,win=doc.defaultView;let pointer=null,ghost=null,frame=null,suppressClick=false;
 const destination=(x,y)=>doc.elementFromPoint?.(x,y)?.closest?.('[data-board-term]');
 const cleanPointer=()=>{if(frame&&win)win.cancelAnimationFrame(frame);frame=null;ghost?.remove();ghost=null;clear();root.querySelector('.semester-board')?.classList.remove('semester-dragging');};
 const autoscroll=()=>{if(!pointer?.moved||!win)return;const height=win.innerHeight,delta=pointer.y<75?-13:pointer.y>height-75?13:0;if(delta)win.scrollBy(0,delta);frame=win.requestAnimationFrame(autoscroll);};
 root.addEventListener('pointerdown',e=>{const handle=e.target.closest?.('[data-drag-course]');if(!handle||handle.disabled||e.button!==0||pointer)return;pointer={pointerId:e.pointerId,id:handle.dataset.dragCourse,handle,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};handle.setPointerCapture?.(e.pointerId);});
 root.addEventListener('pointermove',e=>{if(!pointer||pointer.pointerId!==e.pointerId)return;pointer.x=e.clientX;pointer.y=e.clientY;if(!pointer.moved&&Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)<7)return;e.preventDefault();if(!pointer.moved){pointer.moved=true;root.querySelector('.semester-board')?.classList.add('semester-dragging');ghost=doc.createElement('div');ghost.className='semester-drag-ghost';ghost.textContent=pointer.handle.closest('[data-board-row]')?.querySelector('.board-course-name')?.textContent||'Move course';ghost.setAttribute('aria-hidden','true');doc.body.appendChild(ghost);autoscroll();}ghost.style.left=(e.clientX+14)+'px';ghost.style.top=(e.clientY+14)+'px';clear();const target=destination(e.clientX,e.clientY);if(target&&target.dataset.boardTerm!=='prior')target.classList.add('semester-drop-active');});
 root.addEventListener('pointerup',e=>{if(!pointer||pointer.pointerId!==e.pointerId)return;const action=pointer,target=destination(e.clientX,e.clientY);pointer=null;action.handle.releasePointerCapture?.(e.pointerId);cleanPointer();if(!action.moved)return;suppressClick=true;setTimeout(()=>{suppressClick=false;},0);if(target&&target.dataset.boardTerm!=='prior')controller.moveBoardCourse(action.id,target.dataset.boardTerm);});
 root.addEventListener('pointercancel',()=>{pointer=null;cleanPointer();});
 root.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation();suppressClick=false;}},true);
 root.addEventListener('dragstart',e=>{if(pointer){e.preventDefault();return;}});
 root.addEventListener('toggle',e=>{if(e.target.matches?.('[data-board-term]'))controller.boardToggle(e.target.dataset.boardTerm,e.target.open);},true);
 root.addEventListener('dragstart',e=>{if(e.defaultPrevented)return;const handle=e.target.closest?.('[data-drag-course]');if(!handle||handle.disabled)return;dragged=handle.dataset.dragCourse;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged);root.querySelector('.semester-board')?.classList.add('semester-dragging');});
 root.addEventListener('dragover',e=>{const target=section(e);if(!dragged||!target||target.dataset.boardTerm==='prior')return;e.preventDefault();e.dataTransfer.dropEffect='move';clear();target.classList.add('semester-drop-active');});
 root.addEventListener('drop',e=>{const target=section(e);if(!dragged||!target||target.dataset.boardTerm==='prior')return;e.preventDefault();const id=dragged;dragged='';clear();root.querySelector('.semester-board')?.classList.remove('semester-dragging');controller.moveBoardCourse(id,target.dataset.boardTerm);});
 root.addEventListener('dragend',()=>{dragged='';clear();root.querySelector('.semester-board')?.classList.remove('semester-dragging');});
}
